('essential', (SELECT id FROM flux.brands WHERE slug='flux'), (SELECT id FROM flux.categories WHERE slug='lineas'), 'Essential', 'Multinutriente diario de base.', 'Nuestra base diaria: vitaminas del complejo B, minerales y micronutrientes seleccionados para acompañar tu energía y tu rutina.', 'Contribuye a la energía diaria, apoya el sistema inmune y complementa una alimentación variada.', 'Complejo B, vitamina C, vitamina D3, zinc, magnesio bisglicinato, selenio.', '2 cápsulas por día con el desayuno, con un vaso de agua.', '60 cápsulas · 30 días de uso.', 185000, 159000, 'PYG', 42, 'Más vendido', TRUE, 0, TRUE, 0),
('active', (SELECT id FROM flux.brands WHERE slug='flux'), (SELECT id FROM flux.categories WHERE slug='lineas'), 'Active', 'Rendimiento y recuperación.', 'Pensado para días activos: aminoácidos, magnesio y adaptógenos que acompañan el rendimiento y la recuperación.', 'Apoya el rendimiento físico, contribuye a la recuperación muscular y acompaña la resistencia.', 'L-carnitina, magnesio, ashwagandha, vitamina B6, potasio.', '2 cápsulas antes de la actividad física.', '60 cápsulas · 30 días de uso.', 195000, NULL, 'PYG', 18, 'Nuevo', TRUE, 1, TRUE, 10),
('mental', (SELECT id FROM flux.brands WHERE slug='flux'), (SELECT id FROM flux.categories WHERE slug='lineas'), 'Mental Balance', 'Foco y claridad sostenida.', 'Foco y equilibrio: nootrópicos suaves y adaptógenos para acompañar la concentración y la calma en días exigentes.', 'Acompaña la concentración, apoya el manejo del estrés cotidiano y contribuye al descanso.', 'L-teanina, bacopa monnieri, omega 3 vegetal, vitamina B12, magnesio.', '1 cápsula a la mañana y 1 al mediodía.', '60 cápsulas · 30 días de uso.', 189000, NULL, 'PYG', 27, 'Recomendado', TRUE, 2, TRUE, 20),
('women', (SELECT id FROM flux.brands WHERE slug='flux'), (SELECT id FROM flux.categories WHERE slug='lineas'), 'Women', 'Salud integral femenina.', 'Un soporte integral para el bienestar femenino en cada etapa: hierro, folato y micronutrientes clave.', 'Apoya el equilibrio hormonal, contribuye a reducir el cansancio y acompaña la salud de piel y cabello.', 'Hierro bisglicinato, folato, vitamina D3, calcio, biotina, vitamina E.', '2 cápsulas por día con una comida principal.', '60 cápsulas · 30 días de uso.', 199000, 169000, 'PYG', 31, 'Promo', TRUE, 3, TRUE, 30),
