-- =====================================================================
-- FLUX · SEED categorías, objetivos y productos (61 productos)
-- Correr DESPUÉS del schema y las policies. ON CONFLICT idempotente.
-- =====================================================================

-- 1. CATEGORIES
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, color = EXCLUDED.color;

-- 2. GOALS
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, color = EXCLUDED.color;

-- 3. PRODUCTS
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, short_description = EXCLUDED.short_description,
  description = EXCLUDED.description, benefits = EXCLUDED.benefits,
  ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use,
  presentation = EXCLUDED.presentation, price = EXCLUDED.price,
  promo_price = EXCLUDED.promo_price, stock = EXCLUDED.stock,
  badge = EXCLUDED.badge, featured = EXCLUDED.featured,
  featured_order = EXCLUDED.featured_order, updated_at = NOW();

-- 3b. PRODUCT_IMAGES (imagen principal por producto)
ON CONFLICT DO NOTHING;

-- 4. PRODUCT_GOALS (join)
ON CONFLICT DO NOTHING;
